SELECT p.gender, AVG(a.los) AS average_los, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY a.los) AS p75_los, PERCENTILE_CONT(0.90) WITHIN GROUP (ORDER BY a.los) AS p90_los, COUNT(DISTINCT CASE WHEN a.discharge_location = 'home' THEN a.hadm_id END) AS home_discharges, COUNT(DISTINCT CASE WHEN a.discharge_location = 'facility' THEN a.hadm_id END) AS facility_discharges, COUNT(DISTINCT CASE WHEN a.deathtime IS NOT NULL THEN a.hadm_id END) AS deaths FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM CURRENT_DATE) - p.anchor_year BETWEEN 52 AND 62 AND a.admission_type != 'elective' AND a.discharge_time BETWEEN a.admittime AND CURRENT_TIME - INTERVAL '7 days' GROUP BY p.gender;